#!/usr/bin/env bash

# IncrementalBackup_FileNames-WorkFlow.sh
# Generated By Google AI
# Confirmed working script 

# Exit immediately if a command exits with a non-zero status
set -euo pipefail

# --- CONFIGURATION ---
TARGET_DIR="./backups"
SOURCE_DIR="/path/to/source_data"
BASE_NAME=$(date +%Y%m%d)
EXTENSION=".tar.gz"

# Ensure the backup directory exists
mkdir -p "$TARGET_DIR"

# --- SUFFIX GENERATION LOGIC ---
FILENAME="${BASE_NAME}${EXTENSION}"
FULL_PATH="${TARGET_DIR}/${FILENAME}"

COUNTER=1
while [ -f "$FULL_PATH" ]; do
    FILENAME="${BASE_NAME}-${COUNTER}${EXTENSION}"
    FULL_PATH="${TARGET_DIR}/${FILENAME}"
    ((COUNTER++))
done

# --- EXECUTION CHECK ---
echo "Creating backup: $FULL_PATH"

if tar -czf "$FULL_PATH" -C "$SOURCE_DIR" . ; then
    echo "✅ Backup completed successfully!"
else
    echo "❌ Error: Backup failed." >&2
    exit 1
fi
